  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface Artwork {
  id: number;
  title: string;
  category: 'Peinture' | 'Sculpture';
  imageUrl: string;
  year: string;
}

export enum Section {
  Home = 'home',
  Gallery = 'gallery',
  ArtTherapy = 'art-therapy',
  About = 'about',
  Contact = 'contact'
}

import { Artwork } from './types';

export const ARTWORKS: Artwork[] = [
  { id: 1, title: 'Éveil Féminin I', category: 'Peinture', imageUrl: 'https://picsum.photos/seed/art1/800/1000', year: '2023' },
  { id: 2, title: 'Structure d\'Âme', category: 'Sculpture', imageUrl: 'https://picsum.photos/seed/sculpt1/800/800', year: '2022' },
