export const BIO_TEXT = "Je suis artiste peintre et art-thérapeute, avec plus de dix années de pratique artistique. Mon travail s’inscrit dans une recherche continue autour de l’expression émotionnelle, de la matière et du lien entre l’art et le mieux-être. Ma démarche artistique se caractérise par une exploration de supports variés, allant de la peinture grand format à la sculpture métallique. Le féminin occupe une place centrale dans mon univers artistique. Mon processus créatif est intuitif et guidé par une forte exigence intérieure. Parallèlement à ma pratique artistique, je développe une activité en art-thérapie. À travers mon travail, j’affirme une conviction essentielle : l’art est à la fois un acte esthétique et une expérience profondément humaine.";

import React, { useState, useEffect } from 'react';
import Navbar from './components/Navbar';
import Hero from './components/Hero';
import Gallery from './components/Gallery';
import Bio from './components/Bio';
import ArtTherapy from './components/ArtTherapy';
import Footer from './components/Footer';

const App: React.FC = () => {
  const [activeSection, setActiveSection] = useState('home');

  useEffect(() => {
    const handleScroll = () => {
      const sections = ['home', 'gallery', 'art-therapy', 'about', 'contact'];
      const scrollPosition = window.scrollY + 100;

      for (const section of sections) {
        const element = document.getElementById(section);
        if (element) {
          const { offsetTop, offsetHeight } = element;
          if (scrollPosition >= offsetTop && scrollPosition < offsetTop + offsetHeight) {
            setActiveSection(section);
            break;
          }
        }
      }
    };

    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  return (
    <div className="min-h-screen font-sans selection:bg-zen-clay selection:text-white">
      <Navbar activeSection={activeSection} />

      <main>
        <section id="home">
          <Hero />
        </section>

        <section id="gallery" className="py-24 bg-zen-beige">
          <Gallery />
        </section>

        <section id="about" className="py-24 bg-zen-ivory">
          <Bio />
        </section>

        <section id="art-therapy" className="py-24 bg-zen-beige">
          <ArtTherapy />
        </section>

        <section id="contact" className="py-24 bg-zen-ivory">
          <div className="container mx-auto px-6">
            <h2 className="text-4xl md:text-5xl font-serif text-center mb-16 text-zen-stone italic">Contact</h2>
            <div className="max-w-4xl mx-auto grid md:grid-cols-2 gap-12">
              <div className="space-y-6">
                <p className="text-lg leading-relaxed text-zen-stone font-light italic">
                  Pour toute demande de collaboration, d'acquisition ou de séance d'art-thérapie, n'hésitez pas à me contacter.
                </p>
                <div className="space-y-4 font-light">
                  <p><strong>Lieu :</strong> Casablanca, Maroc</p>
                  <p><strong>Email :</strong> contact@asmaelaaroubi.com</p>
                  <p><strong>Téléphone :</strong> +212 (0) 6 00 00 00 00</p>
                </div>
              </div>
              <form className="space-y-4">
                <input type="text" placeholder="Nom" className="w-full bg-transparent border-b border-zen-taupe/30 py-3 px-1 focus:border-zen-clay outline-none transition-colors" />
                <input type="email" placeholder="Email" className="w-full bg-transparent border-b border-zen-taupe/30 py-3 px-1 focus:border-zen-clay outline-none transition-colors" />
                <textarea rows={4} placeholder="Votre Message" className="w-full bg-transparent border-b border-zen-taupe/30 py-3 px-1 focus:border-zen-clay outline-none transition-colors resize-none"></textarea>
                <button type="submit" className="mt-8 px-12 py-3 border border-zen-stone text-zen-stone hover:bg-zen-stone hover:text-white transition-all tracking-widest uppercase text-xs">
                  Envoyer
                </button>
              </form>
            </div>
          </div>
        </section>
      </main>

      <Footer />
    </div>
  );
};

export default App;

