                  </div>

                  <div className="space-y-6 font-light text-zen-stone/80 text-sm">
                    <div className="flex items-center space-x-4">
                      <div className="w-8 h-px bg-zen-clay"></div>
                      <p>Casablanca, Maroc</p>
