                      className="absolute pointer-events-none border-4 border-white/30 shadow-[0_0_50px_rgba(0,0,0,0.3)] rounded-full z-30 overflow-hidden bg-no-repeat"
                      style={{
                        width: '200px',
                        height: '200px',
                        left: `${magnifierPos.x - 100}px`,
                        top: `${magnifierPos.y - 100}px`,
