      const rotX = ((centerY - y) / centerY) * 20; // Max 20 deg
      setRotation({ x: rotX, y: rotY });
    } else {
      // Calcul de la loupe pour les peintures
      const bgX = (x / width) * 100;
      const bgY = (y / height) * 100;
      setMagnifierPos({ x, y, bgX, bgY });
