            </div>

            <div className="flex items-center space-x-4 pt-10 border-t border-zen-beige">
              <span className="text-[10px] text-zen-taupe font-serif italic">0{currentIndex + 1}</span>
              <div className="flex-1 flex space-x-2">
                {ARTWORKS.map((_, idx) => (
                  <button
                    key={idx}
